import sys
from collections import defaultdict

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges):
    parent = list(range(n))
    rank = [0] * n
    edges.sort()
    mst_weight = 0
    edges_used = 0
    for weight, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_weight += weight
            edges_used += 1
            if edges_used == n - 1:
                break
    return mst_weight if edges_used == n - 1 else -1

input = sys.stdin.read().split()
t = int(input[0])
index = 1
results = []

for _ in range(t):
    n = int(input[index])
    a = list(map(int, input[index + 1:index + 1 + n]))
    index += 1 + n
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            l = a[i] & a[j]
            if l > 0:
                edges.append((l, i, j))
    results.append(kruskal(n, edges))

print('\n'.join(map(str, results)))
